 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** Picks the language for an Accept-Language header value, honoring q-values; `fallback` if none is supported. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const ranges = header
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...rest] = part.trim().split(";");
+      let q = 1;
+      for (const p of rest) {
+        const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(p);
+        if (m) q = Number(m[1]);
+      }
+      if (!Number.isFinite(q) || q < 0 || q > 1) q = 0;
+      return { lang: tag.trim().toLowerCase().split("-")[0], q, index };
+    })
+    .filter((r) => r.q > 0 && r.lang)
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  for (const r of ranges) {
+    if (LANGUAGES.includes(r.lang)) return r.lang;
+  }
+  return fallback;
+}
